 void StopPlayback(){if(recorder!=null)FinishRecording();if(engine!=null)engine.Stop();HideOverlays();if(mediaTitle!=null)mediaTitle.Text="Selecione um canal, filme ou episódio";}
 void ToggleFullscreen(){HideOverlays();if(fullscreen!=null){fullscreen.Close();return;}fullscreen=new Form(){FormBorderStyle=FormBorderStyle.None,WindowState=FormWindowState.Maximized,BackColor=Color.Black,KeyPreview=true};playerPane.Parent=fullscreen;playerPane.Dock=DockStyle.Fill;fullscreen.KeyDown+=(s,e)=>PlayerKeys(e);fullscreen.FormClosing+=(s,e)=>{HideOverlays();overlay.Owner=this;playerBack.Owner=this;playerPane.Parent=playbackHost;playerPane.Dock=DockStyle.Fill;fullscreen=null;lastActivity=DateTime.UtcNow;if(engine!=null)engine.SetWindow(videoSurface.Handle);};fullscreen.Show(this);lastActivity=DateTime.UtcNow;if(engine!=null)engine.SetWindow(videoSurface.Handle);RefreshOverlays();}
 void PlayerKeys(KeyEventArgs e){lastActivity=DateTime.UtcNow;if(e.KeyCode==Keys.Escape&&fullscreen!=null){fullscreen.Close();e.Handled=true;}else if(e.KeyCode==Keys.F11){ToggleFullscreen();e.Handled=true;}else if(e.KeyCode==Keys.Space){if(engine!=null)engine.Pause(engine.State!=4);e.Handled=true;}else if(e.KeyCode==Keys.Left){Jump(-60000);e.Handled=true;}else if(e.KeyCode==Keys.Right){Jump(60000);e.Handled=true;}}
 protected override void OnKeyDown(KeyEventArgs e){if(playbackScreen!=null&&playbackScreen.Visible)PlayerKeys(e);base.OnKeyDown(e);}
 void ToggleRecording(){if(recorder!=null){FinishRecording();return;}if(engine==null||currentUrl==null||engine.State!=3)return;recordPath=Path.Combine(Path.GetTempPath(),"XCIPTV-"+Guid.NewGuid().ToString("N")+".ts");try{recorder=new EmbeddedVlc(vlc,false,true);recorder.Record(currentUrl,recordPath,engine.Seekable?engine.Time:0);recordStarted=DateTime.UtcNow;buttonHints.Show("Gravando. Clique novamente para terminar e salvar.",recordButton,0,-30,3500);}catch{DiscardRecording();MessageBox.Show(this,"Não foi possível iniciar a gravação. O formato ou o limite de conexões do provedor pode impedir esta função.","Gravação");}}
 bool FinishRecording(){if(recorder==null)return true;if(recordDialog)return false;recordDialog=true;try{recorder.Stop();recorder.Dispose();recorder=null;if(engine!=null)engine.Pause(true);if(!File.Exists(recordPath)||new FileInfo(recordPath).Length<188){MessageBox.Show(fullscreen??this,"Nenhum trecho válido foi recebido. O provedor pode limitar conexões ou o formato pode não permitir gravação.","Gravação");DiscardRecording();return true;}if(MessageBox.Show(fullscreen??this,"Deseja salvar o trecho gravado?","Salvar gravação",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){using(var dialog=new SaveFileDialog(){Title="Salvar trecho gravado",InitialDirectory=Environment.GetFolderPath(Environment.SpecialFolder.MyVideos),Filter="Vídeo MPEG-TS (*.ts)|*.ts",DefaultExt="ts",AddExtension=true,FileName=SafeFileName(currentMedia==null?"Trecho":currentMedia.Name)+" - "+DateTime.Now.ToString("yyyy-MM-dd HH-mm-ss")+".ts"}){if(dialog.ShowDialog(fullscreen??this)==DialogResult.OK){File.Copy(recordPath,dialog.FileName,true);MessageBox.Show(fullscreen??this,"Trecho salvo.","Gravação");}}}DiscardRecording();return true;}catch{MessageBox.Show(fullscreen??this,"Não foi possível salvar. O trecho temporário será mantido em:\n"+recordPath,"Gravação");return false;}finally{recordDialog=false;lastActivity=DateTime.UtcNow;}}
 static string SafeFileName(string name){foreach(char c in Path.GetInvalidFileNameChars())name=name.Replace(c,'_');return name.Length>100?name.Substring(0,100):name;}
 void DiscardRecording(){if(recorder!=null){recorder.Dispose();recorder=null;}try{if(recordPath!=null&&File.Exists(recordPath))File.Delete(recordPath);}catch{}recordPath=null;}
 void CloseCinema(){if(recorder!=null)FinishRecording();closingCinema=true;if(cinemaTimer!=null)cinemaTimer.Dispose();if(overlay!=null)overlay.Dispose();if(playerBack!=null)playerBack.Dispose();scrollHint.Dispose();buttonHints.Dispose();}
 static void TestTrace(string value){if(Environment.GetCommandLineArgs().Contains("--smoke-test"))File.AppendAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-trace.txt"),value+Environment.NewLine);}
 void CinemaLayoutTest(){TestTrace("cinema layout");var sample=new Entry(){Name="Filme de demonstração (2026)",Details=new MediaDetails(){Plot="Descrição do conteúdo fornecida pelo catálogo. Elenco, gênero, classificação e data aparecem antes de reproduzir.",Rating="7",Genre="Drama",Date="2026-11-02",Cast="Elenco de demonstração",Director="Direção de demonstração"}};HidePages();detailsScreen.Visible=true;detailsScreen.BringToFront();detailEntry=sample;RenderDetails(sample);AttachHome(detailsScreen);Snapshot("synopsis");if(detailsBack.Top<=detailsPlay.Top||detailsCover.Width<150)throw new Exception("Synopsis controls invalid");ShowPlayback();playingMetadata.Text=sample.Name+Environment.NewLine+sample.Details.Summary;RefreshOverlays();if(!overlay.Visible)throw new Exception("Overlay missing");using(var bitmap=new Bitmap(overlay.Width,overlay.Height)){overlay.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ui-previews","controls.png"));}TestTrace("fullscreen");ToggleFullscreen();lastActivity=DateTime.UtcNow.AddSeconds(-5);RefreshOverlays();if(overlay.Visible||playerBack.Visible)throw new Exception("Idle controls did not hide");lastActivity=DateTime.UtcNow;RefreshOverlays();if(!overlay.Visible||!playerBack.Visible)throw new Exception("Active controls missing");fullscreen.Close();detailsEpoch++;}
}
